feed:
{{- /* For consumed section, include all items; for others, limit to 20 */}}
{{- $pages := .Pages.ByLastmod.Reverse -}}
{{- if ne .Section "margins" }}
  {{- $pages = first 20 $pages -}}
{{- end }}
{{- $self := .OutputFormats.Get "Atom" -}}
{{- $html := .OutputFormats.Get "HTML" -}}
{{- $owner := .Site.Params.copyright_holder | default .Site.Title -}}
{{- $feedTitle := .Title -}}
{{- if eq .Section "made" -}}
  {{- $feedTitle = printf (i18n "feedTitleMade" | default "%s’s Articles") $owner -}}
{{- else if eq .Section "margins" -}}
  {{- $feedTitle = printf (i18n "feedTitleMargins" | default "%s’s Margins") $owner -}}
{{- else if eq .Section "found" -}}
  {{- $feedTitle = printf (i18n "feedTitleFound" | default "%s’s Found") $owner -}}
{{- else if eq .Section "playlists" -}}
  {{- $feedTitle = printf (i18n "feedTitlePlaylists" | default "%s’s Playlists") $owner -}}
{{- end -}}
{{ $feedTitle | htmlUnescape | transform.XMLEscape }}
{{ with $html }}{{ .Permalink }}{{ else }}{{ .Permalink }}{{ end }}
{{ with index $pages 0 }}{{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}{{ else }}{{ now.UTC.Format "2006-01-02T15:04:05Z07:00" }}{{ end }}
{{- with $self }}

{{- end }}
{{- with $html }}

{{- end }}
{{- if .Description }}
{{ .Description | plainify | htmlUnescape | transform.XMLEscape }}
{{- else if .Site.Params.description }}
{{ .Site.Params.description | plainify | htmlUnescape | transform.XMLEscape }}
{{- end }}
Hugo
{{- range $pages }}

  {{ .Title | htmlUnescape | transform.XMLEscape }}

  {{ .Permalink }}
  {{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}
  {{- with .Date }}
  {{ .Format "2006-01-02T15:04:05Z07:00" }}
  {{- end }}

    {{ with .Params.author }}{{ . | htmlUnescape | transform.XMLEscape }}{{ else }}{{ $.Site.Title | htmlUnescape | transform.XMLEscape }}{{ end }}

  {{- with .Params.description }}
  {{ . | plainify | htmlUnescape | transform.XMLEscape }}
  {{- else }}{{ with .Summary }}
  {{ . | plainify | htmlUnescape | transform.XMLEscape }}
  {{- end }}{{ end }}
  {{- /* Thumbnail image for feed readers. Hugo's asset pipeline only
         publishes resources that are *transformed* (e.g. .Resize), so
         we run the image through a small webp resize. This guarantees
         the emitted URL points at a file that will be in public/ and
         keeps the feed payload light. External URLs pass through. */}}
  {{- $img := .Params.img | default .Params.image }}
  {{- $imgURL := "" }}
  {{- $imgType := "image/jpeg" }}
  {{- if $img }}
    {{- if hasPrefix $img "http" }}
      {{- $imgURL = $img }}
    {{- else }}
      {{- $imgRes := resources.Get (strings.TrimPrefix "/" $img) }}
      {{- if $imgRes }}
        {{- $thumb := $imgRes.Resize "800x webp q85" }}
        {{- $imgURL = $thumb.Permalink }}
        {{- $imgType = "image/webp" }}
      {{- else }}
        {{- /* Fallback: treat as a /static/ path */}}
        {{- $imgURL = $img | absURL }}
        {{- $ext := path.Ext $imgURL | lower }}
        {{- if eq $ext ".png" }}{{- $imgType = "image/png" }}
        {{- else if eq $ext ".webp" }}{{- $imgType = "image/webp" }}
        {{- else if eq $ext ".gif" }}{{- $imgType = "image/gif" }}
        {{- else if eq $ext ".avif" }}{{- $imgType = "image/avif" }}
        {{- end }}
      {{- end }}
    {{- end }}

  {{- end }}
  {{ if $imgURL }}<p><img src="{{ $imgURL }}" alt="{{ .Title | htmlUnescape | transform.XMLEscape }}" /></p>{{ end }}{{ .Content | safeHTML }}

{{- end }}
